    "id" uuid NOT NULL,
    "source_citation_id" uuid,
    "unit_feature_id" uuid,
    PRIMARY KEY ("id")
);

CREATE TABLE "civic"."procurements" (
    "buyer_entity_id" uuid NOT NULL,
    "code" varchar(255) NOT NULL,
    "country_id" uuid,
    "id" uuid NOT NULL,
    "procedure_kind_id" uuid NOT NULL,
    "project_id" uuid,
    "published_on" date,
