    "implementing_entity_id" uuid,
    "name" varchar(300) NOT NULL,
    "responsible_institution_id" uuid,
    "scope_unit_feature_id" uuid,
    "source_citation_id" uuid,
    "sponsor_entity_id" uuid,
    "started_on" date,
